  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: 'your-secret-key',
};
passport.use(new JwtStrategy(jwtOptions, (payload, done) => {
  // Verify user from database
  done(null, payload);
}));

// Add logging
app.use(morgan('combined'));

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected users endpoint
app.get('/users', passport.authenticate('jwt', { session: false }), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example of input validation
app.post('/new-user', [
  body('name').notEmpty().trim().escape(),
  body('email').isEmail().normalizeEmail(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  res.json({ status: 'User created' });
});

// Start the server
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

### Summary of Changes
- Added `helmet.js` for security headers.
- Added rate limiting with `express-rate-limit`.
- Added authentication with `passport-jwt`.
- Added logging with `morgan`.
- Added input validation with `express-validator`.
- These changes address the top OWASP concerns and significantly improve the security posture of the application.

